import type { ToolCall, ToolResultMessage } from '@earendil-works/pi-ai';
import type { ComponentType, ReactNode } from 'react';
import { defaultChatLabels } from '../pi-chat/labels';
import type { ArtifactShown, ArtifactFailed } from '@hachej/boring-ui-kit/chat-react';
import type { ChatArtifactsConfig } from '../pi-chat/config';

// Compatibility exports for one release; conversation rules live in the kit.
export { ARTIFACT_TYPES, PRESENT_TOOL, artifactKey, artifactVersionKey, parseArtifact, parsePresentedArtifact, parseTaskArtifact, parseTaskSubject, taskSubjectKey, createTaskArtifact, detectArtifact, collectArtifacts, pendingPresents, presentPath, pendingTitle, pendingId, createPresentAcks, recogniseArtifact } from '@hachej/boring-ui-kit/chat-view';
export type { ArtifactType, ArtifactTarget, ArtifactDescriptor, PresentedArtifact, TaskArtifactDescriptor, TaskSubject, PendingPresent, PresentAnswer, PresentAcksHost, PresentContext, PresentAcks } from '@hachej/boring-ui-kit/chat-view';
import type { ArtifactDescriptor, ArtifactTarget, ArtifactType, PresentedArtifact, TaskArtifactDescriptor, TaskSubject } from '@hachej/boring-ui-kit/chat-view';

/**
 * What an artifact kind's renderer receives: the artifact and its text at the revision shown, the page's URL fragment without `#`
 * (a link such as `#screen=2` can open a place inside the artifact; the panel follows its changes), and `read`: another file of the same
 * workspace as text (its latest revision; undefined when it is missing or not text), for an artifact that links to a file. `revision` is
 * the shown revision, the one a conditional save is made against; `pinned` is true when the panel shows a pinned historical version,
 * which is read-only.
 */
export interface ArtifactKindViewProps {
  readonly artifact: ArtifactDescriptor;
  readonly text: string;
  readonly revision: string;
  readonly pinned: boolean;
  /**
   * The view is loaded and on screen. A kind with `waitsForReady` must call it (once per revision shown): only then does the page
   * acknowledge a `present` call for this file. Other kinds are acknowledged as soon as their file is read, and may ignore it.
   */
  readonly onReady?: (() => void) | undefined;
  /**
   * The view could not be shown (its data failed to load, for example), with a short reason for the agent (at most 200 characters are
   * sent). A `present` call waiting for this file is refused with that reason. A renderer that throws is reported the same way.
   */
  readonly onFailed?: ((reason: string) => void) | undefined;
  readonly fragment?: string | undefined;
  readonly read?: ((path: string) => Promise<string | undefined>) | undefined;
  /**
   * The panel's bar owns the one "…" menu: a view publishes its own entries there (a maquette's guided tours) and clears them with `[]`.
   * Absent outside the panel; the view then draws its own menu.
   */
  readonly setMenu?: ((items: readonly ArtifactMenuEntry[]) => void) | undefined;
  /** The panel bar's controls slot: a view puts its own controls there (the SVG preview and source toggle) and clears them with undefined. */
  readonly setControls?: ((controls: ReactNode) => void) | undefined;
}

/** One entry a kind's view adds to the panel bar's "…" menu (structurally the viewer frame's menu item). */
export interface ArtifactMenuEntry { readonly id: string; readonly label: string; readonly icon: ReactNode; readonly testId: string; readonly separatorBefore: boolean; readonly onSelect: () => void }

/** What a kind's `load` resolves to: a module whose default export is the view. */
export type ArtifactKindView = { readonly default: ComponentType<ArtifactKindViewProps> };

/**
 * An app's own kind of artifact (for example `.maquette.json` files): how its card and the panel name it, its icon, and optionally
 * how the panel draws it. Kinds are consulted in order before the built-in types; the first whose `match` is true wins. A kind
 * adds a presentation only: the descriptor, its type and how it is read are unchanged.
 */
export interface ArtifactKind {
  /** True for the artifacts of this kind, for example `target => target.resource.path.endsWith('.maquette.json')`. */
  readonly match: (target: ArtifactTarget, artifact: ArtifactDescriptor) => boolean;
  /** The kind's name on the card and in the panel bar ("Maquette"). The type's name otherwise. */
  readonly label?: string | undefined;
  /** The card's icon (any component taking `className`, such as a lucide icon). The type's icon otherwise. */
  readonly icon?: ComponentType<{ readonly className?: string; readonly 'aria-hidden'?: boolean | 'true' }> | undefined;
  /** Draws the artifact in the panel (`AgentWorkspace`, `ArtifactPanel`) inside the standard viewer bar, with copy and download. */
  readonly renderer?: ((props: ArtifactKindViewProps) => ReactNode) | undefined;
  /**
   * The view's module, loaded the first time an artifact of this kind opens: the panel wraps it once per kind in `React.lazy` with a
   * spinner in the bar, so the view's code (and its libraries) is not in the page's first bundle. Same props and bar as `renderer`; a kind
   * with both draws with `renderer`. Write it as `() => import('./my-view')` so a bundler splits the view into its own chunk.
   */
  readonly load?: (() => Promise<ArtifactKindView>) | undefined;
  /**
   * A default viewer for a whole type or media type (the built-in Markdown, HTML, SVG, CSV, image and PDF kinds): a host's `viewers`
   * entry for that type wins over it, as it did over the built-in viewers.
   */
  readonly fallback?: boolean | undefined;
  /**
   * The renderer loads asynchronously (a dashboard fetching its data, a sandboxed frame): the panel confirms a `present` of this file
   * only after the renderer calls `onReady`, and refuses it when it calls `onFailed` or throws. With no call, the call ends unconfirmed.
   */
  readonly waitsForReady?: boolean | undefined;
}

/** What every kind shares, whatever its view: the match, its name and icon. The panel's Markdown and HTML editor kinds are kinds too. */
export interface TaskArtifactKind {
  /** Host record viewers are selected separately from file-path matchers. */
  readonly matchTask: (subject: TaskSubject, artifact: TaskArtifactDescriptor) => boolean;
  readonly label?: string | undefined;
  readonly icon?: ArtifactKind['icon'];
}
export type KindMatch = Pick<ArtifactKind, 'match' | 'label' | 'icon'> | TaskArtifactKind;

/** The first kind that matches the artifact; a `match` that throws counts as no match. */
export function artifactKind<Kind extends KindMatch>(artifact: PresentedArtifact, kinds: readonly Kind[] | undefined): Kind | undefined {
  return kinds?.find(kind => { try { return artifact.type === 'task' ? 'matchTask' in kind && kind.matchTask(artifact.subject, artifact) : 'match' in kind && kind.match(artifact.target, artifact); } catch { return false; } });
}

export interface ArtifactHostViewApi {
  /** Report only after the exact subject has loaded and mounted; cleanup reports hidden. */
  readonly onShown: (shown: ArtifactShown) => void;
  readonly onFailed: (failed: ArtifactFailed) => void;
}

/** What the host passes to `PiChat` to turn artifact tool results into cards. */
export interface ArtifactsConfig {
  /** Ambient host only: request task viewers while native present waits. The viewer must still report its loaded mount or failure. Files are unchanged. */
  readonly autoOpenTasks?: boolean | undefined;
  /** The app's own artifact kinds (label, icon, renderer), consulted before the built-in types. */
  readonly kinds?: readonly KindMatch[] | undefined;
  /** The person clicked a card: show this artifact (and revision) in the host's panel. */
  readonly open: (artifact: PresentedArtifact, reports?: ArtifactHostViewApi) => void;
  /** True for the card whose artifact version is on display. */
  readonly isOpen?: (artifact: PresentedArtifact) => boolean;
  /** Recognise a descriptor in a successful tool result that does not carry one itself (for example a document save). */
  readonly detect?: (call: ToolCall, result: ToolResultMessage) => PresentedArtifact | undefined;
  /** How the chat finds a call's artifact (`recogniseArtifact`). With `Card`, it is what makes `PiChat` offer artifacts; `artifactCards` sets both. */
  readonly recognise?: ChatArtifactsConfig['recognise'];
  /** The card the chat draws (`PluggedArtifactCard`). */
  readonly Card?: ChatArtifactsConfig['Card'];
}

/** The artifact's type name: the matching kind's label first, then the chat's name of its type. */
export function typeLabel(artifact: PresentedArtifact, kinds?: readonly KindMatch[], labels: Readonly<Record<ArtifactType, string>> = defaultChatLabels.artifactTypes): string {
  const kind = artifactKind(artifact, kinds);
  if (kind?.label) return kind.label;
  if (artifact.type === 'task') return 'Task';
  return artifact.type === 'code' && artifact.language ? `${labels.code} · ${artifact.language}` : labels[artifact.type];
}

'use client';

import type { ComponentType } from 'react';
import { CheckIcon, ChevronRightIcon, FileCodeIcon, FileTextIcon, GlobeIcon, ImageIcon, PenToolIcon, ListTodoIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Item, ItemContent, ItemDescription, ItemMedia, ItemTitle } from '@/components/ui/item';
import { Shimmer } from '../pi-chat/shimmer';
import { artifactKey, artifactKind, recogniseArtifact, typeLabel } from './artifact';
import type { PresentedArtifact, ArtifactType, KindMatch } from './artifact';
import { useChatText } from '../pi-chat/labels';
import type { ChatArtifactCardProps } from '../pi-chat/config';

const ICONS: Record<ArtifactType, ComponentType<{ readonly 'aria-hidden'?: boolean | 'true' }>> = {
  markdown: FileTextIcon, html: GlobeIcon, svg: ImageIcon, code: FileCodeIcon, canvas: PenToolIcon,
};

/**
 * An artifact in the transcript, as in Claude's chat apps: a compact card with a type icon, the title, the type and the
 * version. Clicking it asks the host to open the artifact. While the `present` call that makes it is still running it is a quiet
 * "opening" card with a shimmer. Rendered outside the activity block, like the question card.
 */
export function ArtifactCard({ artifact, pending, title, open = false, onOpen, kinds }: {
  readonly artifact?: PresentedArtifact | undefined;
  readonly pending?: 'presenting';
  readonly title?: string | undefined;
  readonly open?: boolean;
  readonly onOpen?: ((artifact: PresentedArtifact) => void) | undefined;
  /** The app's artifact kinds (`ArtifactsConfig.kinds`): their label and icon win over the type's. */
  readonly kinds?: readonly KindMatch[] | undefined;
}) {
  const { labels } = useChatText();
  if (!artifact) {
    return <Item variant="outline" size="sm" data-testid="artifact-card" data-state={pending ?? 'presenting'} role="status" aria-busy="true" className="my-2 text-start">
      <ItemMedia variant="image"><Item variant="muted" size="xs" className="min-h-full justify-center"><ItemMedia variant="icon"><FileTextIcon aria-hidden="true" /></ItemMedia></Item></ItemMedia>
      <ItemContent className="min-w-0 basis-0">
        <ItemTitle data-testid="artifact-title"><Shimmer>{title ?? labels.artifact}</Shimmer></ItemTitle>
        <ItemDescription><Shimmer>{labels.opening}</Shimmer></ItemDescription>
      </ItemContent>
    </Item>;
  }
  const kind = artifactKind(artifact, kinds);
  const Icon = kind?.icon ?? (artifact.type === 'task' ? ListTodoIcon : ICONS[artifact.type]);
  const ordinal = artifact.type === 'task' ? undefined : artifact.ordinal;
  return <Button variant={open ? 'secondary' : 'outline'} disabled={!onOpen} onClick={() => onOpen?.(artifact)}
    data-testid="artifact-card" data-state="ready" data-artifact-id={artifactKey(artifact)} data-artifact-revision={artifact.type === 'task' ? undefined : artifact.revision} data-artifact-version={ordinal} data-artifact-type={artifact.type} data-artifact-kind={kind?.label}
    data-open={open ? 'true' : undefined} aria-pressed={onOpen ? open : undefined} aria-label={labels.openArtifact(artifact.title, ordinal)}
    className="my-2 h-auto min-h-12! w-full max-w-md justify-start gap-2.5 text-left">
    <ItemMedia variant="image"><Item variant="muted" size="xs" className="min-h-full justify-center"><Icon aria-hidden="true" /></Item></ItemMedia>
    <span className="flex min-w-0 flex-1 flex-col">
      <span data-testid="artifact-title" className="truncate">{artifact.title}</span>
      <span className="truncate text-xs text-muted-foreground"><span data-testid="artifact-type">{typeLabel(artifact, kinds, labels.artifactTypes)}</span>{ordinal !== undefined && <> · <span data-testid="artifact-version">{labels.version(ordinal)}</span></>}</span>
    </span>
    {open ? <CheckIcon data-icon="inline-end" aria-hidden="true" /> : <ChevronRightIcon data-icon="inline-end" aria-hidden="true" />}
  </Button>;
}

/** `ArtifactCard` as the chat's `artifacts.Card`: the chat hands back the descriptor `recogniseArtifact` found. */
export function PluggedArtifactCard({ artifact, open, onOpen, kinds }: ChatArtifactCardProps) {
  const descriptor = artifact.state === 'ready' ? artifact.descriptor as PresentedArtifact : undefined;
  return <ArtifactCard artifact={descriptor} title={artifact.title} {...(artifact.state === 'ready' ? {} : { pending: artifact.state })}
    open={open} onOpen={onOpen ? () => onOpen() : undefined} kinds={kinds as readonly KindMatch[] | undefined} />;
}

/** What makes `PiChat` offer artifacts: `<PiChat artifacts={{ open, isOpen, kinds, ...artifactCards }} />` (`withChatPlugins` adds it). */
export const artifactCards = { recognise: recogniseArtifact, Card: PluggedArtifactCard } as const;
